// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address user = address(0x1234);
        vm.deal(user, 1 ether);
        vm.prank(user);
        (bool sent, ) = address(c).call{value: 1 ether}("");
        require(sent, "deposit failed");

        // Now try to withdraw
        vm.prank(user);
        try c.withdraw() {
            // Reference succeeds: user gets ether and balance becomes 0
            assertTrue(c.balances(user) == 0 && address(user).balance == 1 ether);
        } catch {
            // Bug reverts: user has 0 balance in contract but no ether received
            assertTrue(c.balances(user) == 0 && address(user).balance == 0 ether);
        }
    }
}
